package com.ebuddy.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="message") public class MessageEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="message_id") UUID id; @Column(name="sender_user_id",nullable=false) UUID senderUserId; @Column(name="recipient_user_id",nullable=false) UUID recipientUserId; @Column(name="client_message_id",nullable=false,length=64) String clientMessageId; @Column(name="sequence_no",nullable=false,insertable=false,updatable=false) Long sequence; @Column(nullable=false,length=4096) String body; @Enumerated(EnumType.STRING) @Column(nullable=false) MessageState status=MessageState.sent; @Column(name="created_at",nullable=false) Instant createdAt=Instant.now(); @Column(name="delivered_at") Instant deliveredAt; @Column(name="read_at") Instant readAt; protected MessageEntity(){} public MessageEntity(UUID f,UUID t,String c,String b){senderUserId=f;recipientUserId=t;clientMessageId=c;body=b;} public UUID getId(){return id;} public UUID getSenderUserId(){return senderUserId;} public UUID getRecipientUserId(){return recipientUserId;} public String getClientMessageId(){return clientMessageId;} public Long getSequence(){return sequence;} public String getBody(){return body;} public MessageState getStatus(){return status;} public Instant getCreatedAt(){return createdAt;} public Instant getDeliveredAt(){return deliveredAt;} public Instant getReadAt(){return readAt;} public void markDelivered(){if(status==MessageState.sent){status=MessageState.delivered;deliveredAt=Instant.now();}} public void markRead(){if(status!=MessageState.read){markDelivered();status=MessageState.read;readAt=Instant.now();}} }
